/** 下端だけを宣言した生リテラルの prop 定義（Box の `layerBlur` と同じ形）。 */
function definitionWithLowerBound() {
  return {
    domain: "literal",
    literalType: "number",
    range: { min: 0 },
    group: "appearance",
  } as const;
}

test("下端だけを宣言した prop に下端そのものの値を設定するとエラーにならない", () => {
  expect(
    PropDefinition.collectErrors(
      definitionWithLowerBound(),
      { name: "layerBlur", value: 0 },
      TokenSet.empty(),
    ),
  ).toEqual([]);
});

test("下端だけを宣言した prop に -Infinity を設定すると range-violation になる", () => {
  expect(
    PropDefinition.collectErrors(
      definitionWithLowerBound(),
      { name: "layerBlur", value: Number.NEGATIVE_INFINITY },
      TokenSet.empty(),
    ),
  ).toEqual([
    expect.objectContaining({ kind: "range-violation", prop: "layerBlur" }),
  ]);
});

test("数値の生リテラル prop には下端だけの値域を宣言できる", () => {
  const definition = {
    domain: "literal",
    literalType: "number",
    range: { min: 0 },
    group: "appearance",
  } as const satisfies LiteralPropDefinition;

  expectTypeOf(definition.range).toEqualTypeOf<{ readonly min: 0 }>();
});

test("数値の生リテラル prop には下端の無い値域を宣言できない", () => {
  const definition = {
    domain: "literal",
    literalType: "number",
    // @ts-expect-error 値域は下端を必ず持つ
    range: { max: 1 },
    group: "appearance",
  } as const satisfies LiteralPropDefinition;

  expectTypeOf(definition.literalType).toEqualTypeOf<"number">();

test("Box の layerBlur は appearance 節の生リテラルの number でデフォルトが 0", () => {
  expect(BoxSchema.props.layerBlur).toMatchObject({
    domain: "literal",
    literalType: "number",
    default: 0,
    group: "appearance",
  });
});

test("Box の layerBlur は 0 の下端だけを範囲に宣言する", () => {
  expect(BoxSchema.props.layerBlur.range).toEqual({ min: 0 });
});

test("Box の backdropBlur は appearance 節の生リテラルの number でデフォルトが 0", () => {
  expect(BoxSchema.props.backdropBlur).toMatchObject({
    domain: "literal",
    literalType: "number",
    default: 0,
    group: "appearance",
  });
});

test("Box の backdropBlur は 0 の下端だけを範囲に宣言する", () => {
  expect(BoxSchema.props.backdropBlur.range).toEqual({ min: 0 });
});

test("Ellipse の Appearance 節は、影の直後に layerBlur・backdropBlur の順で並べる", () => {
  const names = propNamesInSection(ellipseSelection({}), "appearance");
  const afterShadow = names.indexOf("shadow") + 1;

  expect(names.slice(afterShadow, afterShadow + 2)).toEqual([
    "layerBlur",
    "backdropBlur",
  ]);
});

