  expect("backdrop-filter" in compiled.element.style).toBe(false);
});

test("props で背後のぼかしを指定しても artboard の背後はぼかさない", () => {
  const props = Artboard.boxProps(
    Artboard.create({
      name: "login-screen",
      width: 375,
      height: 812,
      props: { backdropBlur: 8 },
    }),
  );

  expect(props.backdropBlur).toBe(0);
});

test("props でノード自身のぼかしを指定すると artboard はその値で解決される", () => {
  const props = Artboard.boxProps(
    Artboard.create({
      name: "login-screen",
      width: 375,
      height: 812,
      props: { layerBlur: 8 },
    }),
  );

  expect(props.layerBlur).toBe(8);
});

test("読み捨てる prop でも、artboard の props に負の背後のぼかしを書くと範囲違反のエラーになる", () => {
  const errors = collectSingleArtboardErrors({ backdropBlur: -1 });

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "range-violation",
      nodeName: "screen",
      prop: "backdropBlur",
    }),
  ]);
});

test("Box に負の layerBlur を指定すると range-violation エラーになる", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [{ name: "box-1", type: "Box", props: { layerBlur: -1 } }],
      },
    ],
  });

  expect(DesignDocument.collectErrors(document)).toEqual([
    expect.objectContaining({
      kind: "range-violation",
      nodeName: "box-1",
      prop: "layerBlur",
    }),
  ]);
});

